import{_ as i}from"./chunks/digital_airspeed_sensor.CYKOvru3.js";import{_ as o,C as t,o as n,c as l,al as a,E as s,a as d}from"./chunks/framework.7vp1BMOE.js";const A=JSON.parse('{"title":"Airspeed Sensors","description":"","frontmatter":{},"headers":[],"relativePath":"en/sensor/airspeed.md","filePath":"en/sensor/airspeed.md"}'),c={name:"en/sensor/airspeed.md"};function p(h,e,f,_,u,g){const r=t("Badge");return n(),l("div",null,[e[0]||(e[0]=a('<h1 id="airspeed-sensors" tabindex="-1">Airspeed Sensors <a class="header-anchor" href="#airspeed-sensors" aria-label="Permalink to &quot;Airspeed Sensors&quot;">​</a></h1><p>Airspeed sensors are <em>highly recommended</em> for fixed-wing and VTOL frames. They are so important because the autopilot does not have other means to detect stall. For fixed-wing flight it is the airspeed that guarantees lift — not ground speed!</p><p><img src="'+i+'" alt="Digital airspeed sensor"></p><h2 id="hardware-options" tabindex="-1">Hardware Options <a class="header-anchor" href="#hardware-options" aria-label="Permalink to &quot;Hardware Options&quot;">​</a></h2><p>Recommended digital airspeed sensors include:</p><ul><li>Based on <a href="https://en.wikipedia.org/wiki/Pitot_tube" target="_blank" rel="noreferrer">Pitot tube</a><ul><li>I2C MEAS Spec series (e.g. <a href="https://www.te.com/en/product-20003581-00.html" target="_blank" rel="noreferrer">MS4525DO</a>, <a href="https://www.te.com/usa-en/product-CAT-BLPS0003.html" target="_blank" rel="noreferrer">MS5525</a>) <ul><li><a href="https://store.3dr.com/airspeed-sensor-jst-gh-ms4525do/" target="_blank" rel="noreferrer">mRo I2C Airspeed Sensor JST-GH MS4525DO</a> (3DR store)</li><li><a href="https://store-drotek.com/793-digital-differential-airspeed-sensor-kit-.html" target="_blank" rel="noreferrer">Digital Differential Airspeed Sensor Kit - MS4525DO</a> (Drotek).</li><li><a href="https://holybro.com/collections/sensors/products/digital-air-speed-sensor-standard" target="_blank" rel="noreferrer">Holybro Digital Air Speed Sensor - MS4525DO</a></li><li><a href="https://holybro.com/collections/sensors/products/digital-air-speed-sensor-standard" target="_blank" rel="noreferrer">Holybro Digital Air Speed Sensor - MS5525DSO</a></li></ul></li><li>I2C Sensirion series (e.g. SDP33) <ul><li><a href="https://docs.thunderfly.cz/avionics/TFPITOT01/" target="_blank" rel="noreferrer">ThunderFly TFPITOT01 Lightweight Pitot Tube</a></li><li><a href="https://store-drotek.com/848-sdp3x-airspeed-sensor-kit-sdp33.html" target="_blank" rel="noreferrer">Drotek SDP3x Airspeed Sensor Kit</a></li></ul></li><li>I2C <em>Amphenol All Sensors</em> Digital Low Voltage R-Series (DLVR) Pressure Sensors. Continuous-sampling sensors only (see for <a href="./../advanced_config/parameter_reference#SENS_EN_DLVR">SENS_EN_DLVR</a> for supported sensors). <ul><li><a href="https://www.mateksys.com/?portfolio=aspd-dlvr" target="_blank" rel="noreferrer">MATEKSYS Digital AirSpeed sensor ASPD-DLVR</a></li><li><a href="https://rcdrone.top/products/matek-mateksys-digital-airspeed-sensor-aspd-dlvr" target="_blank" rel="noreferrer">RCDrone Digital AirSpeed sensor ASPD-DLVR</a></li></ul></li><li>DroneCAN interface <ul><li><a href="https://holybro.com/collections/sensors/products/high-precision-dronecan-airspeed-sensor-dlvr" target="_blank" rel="noreferrer">Holybro High Precision DroneCAN Airspeed Sensor - DLVR</a></li><li><a href="https://docs.raccoonlab.co/guide/airspeed/" target="_blank" rel="noreferrer">RaccoonLab Cyphal/CAN and DroneCAN Airspeed Sensor - MS4525DO</a></li><li><a href="https://www.tindie.com/products/avionicsanonymous/uavcan-air-data-computer-airspeed-sensor/" target="_blank" rel="noreferrer">Avionics Anonymous Air Data Computer with OAT probe</a></li><li><a href="https://wiki.uav-dev.com/en/product/airspeed/auav" target="_blank" rel="noreferrer">UAV-DEV GmbH DroneCAN Airspeed and Barometer Sensor - AUAV</a></li></ul></li></ul></li><li>Based on <a href="https://en.wikipedia.org/wiki/Venturi_effect" target="_blank" rel="noreferrer">Venturi effect</a><ul><li><a href="./airspeed_tfslot">TFSLOT</a> Venturi effect airspeed sensor.</li></ul></li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="enable-airspeed-sensors" tabindex="-1">Enable Airspeed Sensors <a class="header-anchor" href="#enable-airspeed-sensors" aria-label="Permalink to &quot;Enable Airspeed Sensors&quot;">​</a></h3><p>Airspeed sensor drivers are not started automatically. Enable each driver and/or variant using its <a href="./../advanced_config/parameters">corresponding parameter</a>:</p><ul><li><strong><a href="./../modules/modules_driver_airspeed_sensor#sdp3x">Sensirion SDP3X</a></strong> — <a href="./../advanced_config/parameter_reference#SENS_EN_SDP3X">SENS_EN_SDP3X</a></li><li><strong><a href="./../modules/modules_driver_airspeed_sensor#ms4525do">TE MS4525</a></strong> — <a href="./../advanced_config/parameter_reference#SENS_EN_MS4525DO">SENS_EN_MS4525DO</a></li><li><strong><a href="./../modules/modules_driver_airspeed_sensor#ms5525dso">TE MS5525</a></strong> — <a href="./../advanced_config/parameter_reference#SENS_EN_MS5525DS">SENS_EN_MS5525DS</a></li><li><strong>Eagle Tree airspeed sensor:</strong> — <a href="./../advanced_config/parameter_reference#SENS_EN_ETSASPD">SENS_EN_ETSASPD</a></li><li><strong><a href="./../modules/modules_driver_airspeed_sensor#dlvr">Amphenol All Sensors DLVR</a> (continuous-sampling sensors only)</strong> — <a href="./../advanced_config/parameter_reference#SENS_EN_DLVR">SENS_EN_DLVR</a></li></ul><p>You should also check <a href="./../advanced_config/parameter_reference#ASPD_PRIMARY">ASPD_PRIMARY</a> is <code>1</code> (see next section - this is the default).</p><h3 id="multiple-airspeed-sensors" tabindex="-1">Multiple Airspeed Sensors <a class="header-anchor" href="#multiple-airspeed-sensors" aria-label="Permalink to &quot;Multiple Airspeed Sensors&quot;">​</a></h3>',12)),s(r,{type:"tip",text:"main (PX4 v2.0)"}),e[1]||(e[1]=d()),s(r,{type:"tip",text:"Experimental"}),e[2]||(e[2]=a('<div class="warning custom-block"><p class="custom-block-title">Experimental</p><p>Using multiple airspeed sensors is experimental.</p></div><p>PX4 supports up to three airspeed sensors. Each sensor is converted to airspeed independently, keeps its own zero-offset calibration, and is validated separately, so the selector can fall back to a healthy sensor if one fails in flight.</p><h4 id="selecting-the-primary-sensor" tabindex="-1">Selecting the Primary Sensor <a class="header-anchor" href="#selecting-the-primary-sensor" aria-label="Permalink to &quot;Selecting the Primary Sensor&quot;">​</a></h4><p><a href="./../advanced_config/parameter_reference#ASPD_PRIMARY">ASPD_PRIMARY</a> selects the source that is <em>preferred</em>:</p><ul><li><code>0</code>: Groundspeed minus windspeed</li><li><code>1</code>: Airspeed sensor 1 (default)</li><li><code>2</code>: Airspeed sensor 2</li><li><code>3</code>: Airspeed sensor 3</li><li><code>4</code>: Thrust-based (synthetic) airspeed</li></ul><p>The sensor numbers <code>1</code>, <code>2</code> and <code>3</code> refer to the <strong>calibration entry</strong> the sensor owns (recorded in <code>CAL_DPRES{n-1}_ID</code>).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Calibrate every sensor before relying on <code>ASPD_PRIMARY</code>.</p></div><h4 id="failover" tabindex="-1">Failover <a class="header-anchor" href="#failover" aria-label="Permalink to &quot;Failover&quot;">​</a></h4><p>The preferred sensor is used while it passes the airspeed checks (<a href="./../advanced_config/parameter_reference#ASPD_DO_CHECKS">ASPD_DO_CHECKS</a> configures which checks run). If it fails, the selector switches to another valid sensor, preferring the configured primary.</p><p><a href="./../advanced_config/parameter_reference#ASPD_FALLBACK">ASPD_FALLBACK</a> controls what happens when <em>no</em> sensor is usable: stay without airspeed, fall back to groundspeed minus windspeed, or fall back to thrust-based airspeed.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>By default a sensor that fails its checks stays failed until the next reboot (<a href="./../advanced_config/parameter_reference#ASPD_FS_T_START">ASPD_FS_T_START</a> is <code>-1</code>). Set it to a positive number of seconds to allow a recovered sensor to be used again in the same flight.</p></div><p>The selected sensor is then used to <a href="./../advanced_config/tuning_the_ecl_ekf#airspeed">supply data to the estimator (EKF2)</a> and the controllers.</p><h4 id="per-sensor-calibration" tabindex="-1">Per-Sensor Calibration <a class="header-anchor" href="#per-sensor-calibration" aria-label="Permalink to &quot;Per-Sensor Calibration&quot;">​</a></h4><p>Each sensor stores its own zero offset in <code>CAL_DPRES{n}_OFF</code>, linked to the sensor&#39;s device ID in <code>CAL_DPRES{n}_ID</code>. A single <a href="./../config/airspeed">airspeed calibration</a> calibrates every connected sensor.</p><h3 id="sensor-specific-configuration" tabindex="-1">Sensor-specific Configuration <a class="header-anchor" href="#sensor-specific-configuration" aria-label="Permalink to &quot;Sensor-specific Configuration&quot;">​</a></h3><p>Other than enabling the sensor, sensor-specific configuration is often not required. If it is needed, it should be covered in the appropriate sensor page (for example <a href="./airspeed_tfslot#configuration">TFSLOT &gt; Configuration</a>).</p><p>The specific configuration for sensors that do not have a separate page is listed below:</p><ul><li><strong>Sensirion SDP3X:</strong> <a href="./../advanced_config/parameter_reference#CAL_AIR_CMODEL">CAL_AIR_CMODEL</a> (provides overview of required settings), <a href="./../advanced_config/parameter_reference#CAL_AIR_TUBED_MM">CAL_AIR_TUBED_MM</a>, <a href="./../advanced_config/parameter_reference#CAL_AIR_TUBELEN">CAL_AIR_TUBELEN</a>.</li></ul><h2 id="calibration" tabindex="-1">Calibration <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;Calibration&quot;">​</a></h2><p>Airspeed sensors should be calibrated by following the instructions: <a href="./../config/airspeed">Basic Configuration &gt; Airspeed</a>.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>For more advanced validation, configuration and debugging see <a href="./../advanced_config/airspeed_validation">Airspeed Validation</a>.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../config_fw/airspeed_scale_handling">Airspeed Scale Handling</a></li><li><a href="./../advanced_config/tuning_the_ecl_ekf#airspeed">Using PX4&#39;s Navigation Filter (EKF2) &gt; Airspeed</a></li><li><a href="https://github.com/PX4/PX4-Autopilot/tree/main/src/drivers/differential_pressure" target="_blank" rel="noreferrer">Airspeed drivers</a> (source code)</li><li><a href="./../config_vtol/vtol_without_airspeed_sensor">VTOL Without an Airspeed Sensor</a></li></ul>',24))])}const b=o(c,[["render",p]]);export{A as __pageData,b as default};
